window.AUTH=window.AUTH||{};window.AUTH["06-5754"]={"d":"06-5754","id":"2006/06-5754","n":"Rita v. United States","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for the United States","date":"","url":"https://www.justice.gov/osg/media/213126/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/rita-v-united-states-brief-merits","n":105}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep551/usrep551338/usrep551338.pdf","tr":true,"items":[{"t":"case","label":"Blakely v. Washington","cite":"542 U.S. 296","y":2004,"id":"2003/02-1632","sc":1,"op":18,"sum":"The Court held that an exceptional sentence increase based on the judge's determination that Blakely had acted with \"deliberate cruelty\" violated Blakely's Sixth Amendment right to trial by jury.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Braxton v. United States","cite":"500 U.S. 344","y":1991,"id":"1990/90-5358","sc":1,"sum":"The court below misapplied the § 1B1.2(a) proviso.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Brecht v. Abrahamson","cite":"507 U.S. 619","y":1993,"id":"1992/91-7358","sc":1,"sum":"Chief Justice William H. Rehnquist wrote that the \"substantial and injurious effect\" test was preferable to the \"beyond a reasonable doubt\" test in requests for habeas corpus relief. Habeas proceedings are not to be the primary avenue for resolving disputes; Rehnquist called the writ \"an extraordinary remedy\", reserved for the victims of grave injustice.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"op":1,"sum":"The Court found the Act to be valid because although Congress cannot generally delegate its legislative power to another Branch, the nondelegation doctrine does not prevent Congress from obtaining assistance from coordinate Branches.","sumSrc":"Oyez","by":{"0":"17, 24"}},{"t":"case","label":"Ring v. Arizona","cite":"536 U.S. 584","y":2002,"id":"2001/01-488","sc":1,"op":1,"sum":"The Court held that, because Arizona's enumerated aggravating factors operates as \"the functional equivalent of an element of a greater offense,\" the Sixth Amendment requires that they be found by a jury.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"United States v. Alonzo","cite":"435 F.3d 551","y":2006,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/435/551/","op":1,"by":{"0":"11"}},{"t":"case","label":"United States v. Booker","cite":"543 U.S. 220","y":2005,"id":"2004/04-104","sc":1,"op":83,"ar":15,"sum":"The Court held that the Sentencing Guidelines, where they allow judges to enhance sentences using facts not reviewed by juries, violated the Sixth Amendment right to trial by jury. The sentences of Booker and Fanfan, based partly on facts determined only by judges, were therefore unconstitutional.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"United States v. Boscarino","cite":"437 F.3d 634","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/437/634/","op":1,"by":{"0":"11"}},{"t":"case","label":"United States v. Buchanan","cite":"449 F.3d 731","y":2006,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/449/731/","by":{"0":"23, 33"}},{"t":"case","label":"United States v. Cage","cite":"451 F.3d 585","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/451/585/","by":{"0":"18, 37"}},{"t":"case","label":"United States v. Candia","cite":"454 F.3d 468","y":2006,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/454/468/","by":{"0":"11"}},{"t":"case","label":"United States v. Cook","cite":"291 F.3d 1297","y":2002,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/291/1297/","by":{"0":"15"}},{"t":"case","label":"United States v. Cooper","cite":"437 F.3d 324","y":2006,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/437/324/","op":2,"by":{"0":"12, 43"}},{"t":"case","label":"United States v. Cunningham","cite":"429 F.3d 673","y":2005,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/429/673/","op":8,"ar":4,"by":{"0":"43, 50"}},{"t":"case","label":"United States v. Dean","cite":"414 F.3d 725","y":2005,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/414/725/","op":1,"by":{"0":"41"}},{"t":"case","label":"United States v. Dixon","cite":"449 F.3d 194","y":2006,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/449/194/","by":{"0":"32"}},{"t":"case","label":"United States v. Dorceley","cite":"454 F.3d 366","y":2006,"url":"https://www.courtlistener.com/c/F.3d/454/366/","op":1,"by":{"0":"11"}},{"t":"case","label":"United States v. Dragon","cite":"471 F.3d 501","y":2006,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/471/501/","by":{"0":"28, 47"}},{"t":"case","label":"United States v. Fernandez","cite":"443 F.3d 19","y":2006,"url":"https://www.courtlistener.com/c/F.3d/443/19/","op":2,"by":{"0":"12, 43, 50"}},{"t":"case","label":"United States v. Fleming","cite":"397 F.3d 95","y":2005,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/397/95/","by":{"0":"10, 40, 41"}},{"t":"case","label":"United States v. Foreman","cite":"436 F.3d 638","y":2006,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/436/638/","by":{"0":"34"}},{"t":"case","label":"United States v. Gama-Gonzales","cite":"469 F.3d 1109","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/469/1109/","by":{"0":"35"}},{"t":"case","label":"United States v. Green","cite":"436 F.3d 449","y":2006,"url":"https://www.courtlistener.com/c/F.3d/436/449/","op":1,"by":{"0":"8, 11, 46"}},{"t":"case","label":"United States v. Hughes","cite":"401 F.3d 540","y":2005,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/401/540/","by":{"0":"40"}},{"t":"case","label":"United States v. Hunt","cite":"459 F.3d 1180","y":2006,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/459/1180/","by":{"0":"26"}},{"t":"case","label":"United States v. Jimenez-Beltre","cite":"440 F.3d 514","y":2006,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/440/514/","op":1,"by":{"0":"12, 17, 25, 44"}},{"t":"case","label":"United States v. Johnson","cite":"445 F.3d 339","y":2006,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/445/339/","by":{"0":"17, 22, 23, 42"}},{"t":"case","label":"United States v. Jointer","cite":"457 F.3d 682","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/457/682/","by":{"0":"32"}},{"t":"case","label":"United States v. Jones","cite":"445 F.3d 865","y":2006,"url":"https://www.courtlistener.com/c/F.3d/445/865/","by":{"0":"43"}},{"t":"case","label":"United States v. Jordan","cite":"435 F.3d 693","y":2006,"url":"https://www.courtlistener.com/c/F.3d/435/693/","by":{"0":"34"}},{"t":"case","label":"United States v. Kristl","cite":"437 F.3d 1050","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/437/1050/","op":2,"by":{"0":"11"}},{"t":"case","label":"United States v. Lazenby","cite":"439 F.3d 928","y":2006,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/439/928/","by":{"0":"38"}},{"t":"case","label":"United States v. Lewis","cite":"424 F.3d 239","y":2005,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/424/239/","by":{"0":"40"}},{"t":"case","label":"United States v. Lincoln","cite":"413 F.3d 716","y":2005,"url":"https://www.courtlistener.com/c/F.3d/413/716/","op":1,"by":{"0":"11"}},{"t":"case","label":"United States v. Long","cite":"425 F.3d 482","y":2005,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/425/482/","by":{"0":"21"}},{"t":"case","label":"United States v. Lopez-Flores","cite":"444 F.3d 1218","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/444/1218/","by":{"0":"40, 44"}},{"t":"case","label":"United States v. Miqbel","cite":"444 F.3d 1173","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/444/1173/","by":{"0":"40"}},{"t":"case","label":"United States v. Mix","cite":"457 F.3d 806","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/457/806/","by":{"0":"32"}},{"t":"case","label":"United States v. Moreland","cite":"437 F.3d 424","y":2006,"url":"https://www.courtlistener.com/c/F.3d/437/424/","op":2,"by":{"0":"34"}},{"t":"case","label":"United States v. Myers","cite":"439 F.3d 415","y":2006,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/439/415/","op":1,"by":{"0":"34, 37"}},{"t":"case","label":"United States v. Mykytiuk","cite":"415 F.3d 606","y":2005,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/415/606/","op":1,"by":{"0":"11, 23"}},{"t":"case","label":"United States v. Navedo-Concepción","cite":"450 F.3d 54","y":2006,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/450/54/","by":{"0":"27, 28"}},{"t":"case","label":"United States v. Olabanji","cite":"268 F.3d 636","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/268/636/","by":{"0":"15"}},{"t":"case","label":"United States v. Ramirez-Rivera","cite":"241 F.3d 37","y":2001,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/241/37/","by":{"0":"16"}},{"t":"case","label":"United States v. Richardson","cite":"437 F.3d 550","y":2006,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/437/550/","op":1,"by":{"0":"11"}},{"t":"case","label":"United States v. Rivera","cite":"463 F.3d 598","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/463/598/","by":{"0":"11"}},{"t":"case","label":"United States v. Salinas","cite":"365 F.3d 582","y":2004,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/365/582/","by":{"0":"15"}},{"t":"case","label":"United States v. Sam","cite":"467 F.3d 857","y":2006,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/467/857/","by":{"0":"10, 40, 48"}},{"t":"case","label":"United States v. Sanchez-Juarez","cite":"446 F.3d 1109","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/446/1109/","by":{"0":"43"}},{"t":"case","label":"United States v. Scott","cite":"426 F.3d 1324","y":2005,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/426/1324/","by":{"0":"41, 42"}},{"t":"case","label":"United States v. Shelton","cite":"400 F.3d 1325","y":2005,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/400/1325/","by":{"0":"17"}},{"t":"case","label":"United States v. Smith","cite":"2006 WL 3823174","y":2006,"court":"4th Cir. Dec. 29","by":{"0":"28"}},{"t":"case","label":"United States v. Talley","cite":"431 F.3d 784","y":2005,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/431/784/","op":2,"by":{"0":"41, 42"}},{"t":"case","label":"United States v. Terrell","cite":"445 F.3d 1261","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/445/1261/","by":{"0":"22, 33"}},{"t":"case","label":"United States v. Tsosie","cite":"376 F.3d 1210","y":2004,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/376/1210/","by":{"0":"15"}},{"t":"case","label":"United States v. Turbides-Leonardo","cite":"468 F.3d 34","y":2006,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/468/34/","by":{"0":"43"}},{"t":"case","label":"United States v. Tyra","cite":"454 F.3d 686","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/454/686/","by":{"0":"40, 48"}},{"t":"case","label":"United States v. Valtierra-Rojas","cite":"468 F.3d 1235","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/468/1235/","by":{"0":"34"}},{"t":"case","label":"United States v. White Face","cite":"383 F.3d 733","y":2004,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/383/733/","by":{"0":"15"}},{"t":"case","label":"United States v. Williams","cite":"436 F.3d 706","y":2006,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/436/706/","op":1,"by":{"0":"11, 40"}},{"t":"case","label":"United States v. Williams","cite":"456 F.3d 1353","y":2006,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/456/1353/","by":{"0":"32"}},{"t":"case","label":"United States v. Wilson","cite":"350 F. Supp. 2d 910","y":2005,"court":"D. Utah","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/350/910/","by":{"0":"19"}},{"t":"case","label":"Walton v. Arizona","cite":"497 U.S. 639","y":1990,"id":"1989/88-7351","sc":1,"sum":"The Court held that the Arizona method of death penalty sentencing is not arbitrary and does not place an undue burden on the defendant.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"const","label":"Amendment VI, Section 1","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"0":"18"}},{"t":"law","label":"PROTECT Act, Pub. L. No. 108-21","url":"https://www.govinfo.gov/link/plaw/108/public/21","by":{"0":"18"}},{"t":"usc","label":"18 U.S.C. § 3551","url":"https://www.law.cornell.edu/uscode/text/18/3551","stext":{"head":"§3551. Authorized sentences","paras":[[0,"(a) In General.—Except as otherwise specifically provided, a defendant who has been found guilty of an offense described in any Federal statute, including sections 13 and 1153 of this title, other than an Act of Congress applicable exclusively in the District of Columbia or the Uniform Code of Military Justice, shall be sentenced in accordance with the provisions of this chapter so as to achieve the purposes set forth in subparagraphs (A) through (D) of section 3553(a)(2) to the extent that they are applicable in light of all the circumstances of the case."],[0,"(b) Individuals.—An individual found guilty of an offense shall be sentenced, in accordance with the provisions of section 3553, to—"],[1,"(1) a term of probation as authorized by subchapter B;"],[1,"(2) a fine as authorized by subchapter C; or"],[1,"(3) a term of imprisonment as authorized by subchapter D."],[0,"A sentence to pay a fine may be imposed in addition to any other sentence. A sanction authorized by section 3554, 3555, or 3556 may be imposed in addition to the sentence required by this subsection."],[0,"(c) Organizations.—An organization found guilty of an offense shall be sentenced, in accordance with the provisions of section 3553, to—"],[1,"(1) a term of probation as authorized by subchapter B; or"],[1,"(2) a fine as authorized by subchapter C."],[0,"A sentence to pay a fine may be imposed in addition to a sentence to probation. A sanction authorized by section 3554, 3555, or 3556 may be imposed in addition to the sentence required by this subsection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3551?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3551. Authorized sentences","tname":"Crimes and Criminal Procedure","by":{"0":"3"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)","(a)(1)","(a)(2)","(a)(2)(A)","(a)(4)","(a)(4)(A)","(a)(5)","(a)(6)","(b)(1)","(c)","(c)(1)","(c)(2)"],"stext":{"head":"§3553. Imposition of a sentence","paras":[[0,"(a) Factors To Be Considered in Imposing a Sentence.—The court shall impose a sentence sufficient, but not greater than necessary, to comply with the purposes set forth in paragraph (2) of this subsection. The court, in determining the particular sentence to be imposed, shall consider—"],[1,"(1) the nature and circumstances of the offense and the history and characteristics of the defendant;"],[1,"(2) the need for the sentence imposed—"],[2,"(A) to reflect the seriousness of the offense, to promote respect for the law, and to provide just punishment for the offense;"],[2,"(B) to afford adequate deterrence to criminal conduct;"],[2,"(C) to protect the public from further crimes of the defendant; and"],[2,"(D) to provide the defendant with needed educational or vocational training, medical care, or other correctional treatment in the most effective manner;"],[1,"(3) the kinds of sentences available;"],[1,"(4) the kinds of sentence and the sentencing range established for—"],[2,"(A) the applicable category of offense committed by the applicable category of defendant as set forth in the guidelines—"],[3,"(i) issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, subject to any amendments made to such guidelines by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[3,"(ii) that, except as provided in section 3742(g), are in effect on the date the defendant is sentenced; or"],[2,"(B) in the case of a violation of probation or supervised release, the applicable guidelines or policy statements issued by the Sentencing Commission pursuant to section 994(a)(3) of title 28, United States Code, taking into account any amendments made to such guidelines or policy statements by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28);"],[1,"(5) any pertinent policy statement—"],[2,"(A) issued by the Sentencing Commission pursuant to section 994(a)(2) of title 28, United States Code, subject to any amendments made to such policy statement by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[2,"(B) that, except as provided in section 3742(g), is in effect on the date the defendant is sentenced.1"],[1,"(6) the need to avoid unwarranted sentence disparities among defendants with similar records who have been found guilty of similar conduct; and"],[1,"(7) the need to provide restitution to any victims of the offense."],[0,"(b) Application of Guidelines in Imposing a Sentence.—"],[1,"(1) In general.—Except as provided in paragraph (2), the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless the court finds that there exists an aggravating or mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence different from that described. In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission."],[1,"(2) Child crimes and sexual offenses.—"],[2,"(A) 2 Sentencing.—In sentencing a defendant convicted of an offense under section 1201 involving a minor victim, an offense under section 1591, or an offense under chapter 71, 109A, 110, or 117, the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless—"],[3,"(i) the court finds that there exists an aggravating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence greater than that described;"],[3,"(ii) the court finds that there exists a mitigating circumstance of a kind or to a degree, that—"],[4,"(I) has been affirmatively and specifically identified as a permissible ground of downward departure in the sentencing guidelines or policy statements issued under section 994(a) of title 28, taking account of any amendments to such sentencing guidelines or policy statements by Congress;"],[4,"(II) has not been taken into consideration by the Sentencing Commission in formulating the guidelines; and"],[4,"(III) should result in a sentence different from that described; or"],[3,"(iii) the court finds, on motion of the Government, that the defendant has provided substantial assistance in the investigation or prosecution of another person who has committed an offense and that this assistance established a mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence lower than that described."],[0,"In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission, together with any amendments thereto by act of Congress. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission, together with any amendments to such guidelines or policy statements by act of Congress."],[0,"(c) Statement of Reasons for Imposing a Sentence.—The court, at the time of sentencing, shall state in open court the reasons for its imposition of the particular sentence, and, if the sentence—"],[1,"(1) is of the kind, and within the range, described in subsection (a)(4), and that range exceeds 24 months, the reason for imposing a sentence at a particular point within the range; or"],[1,"(2) is not of the kind, or is outside the range, described in subsection (a)(4), the specific reason for the imposition of a sentence different from that described, which reasons must also be stated with specificity in a statement of reasons form issued under section 994(w)(1)(B) of title 28, except to the extent that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32. In the event that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32 the court shall state that such statements were so received and that it relied upon the content of such statements."],[0,"If the court does not order restitution, or orders only partial restitution, the court shall include in the statement the reason therefor. The court shall provide a transcription or other appropriate public record of the court's statement of reasons, together with the order of judgment and commitment, to the Probation System and to the Sentencing Commission,,3 and, if the sentence includes a term of imprisonment, to the Bureau of Prisons."],[0,"(d) Presentence Procedure for an Order of Notice.—Prior to imposing an order of notice pursuant to section 3555, the court shall give notice to the defendant and the Government that it is considering imposing such an order. Upon motion of the defendant or the Government, or on its own motion, the court shall—"],[1,"(1) permit the defendant and the Government to submit affidavits and written memoranda addressing matters relevant to the imposition of such an order;"],[1,"(2) afford counsel an opportunity in open court to address orally the appropriateness of the imposition of such an order; and"],[1,"(3) include in its statement of reasons pursuant to subsection (c) specific reasons underlying its determinations regarding the nature of such an order."],[0,"Upon motion of the defendant or the Government, or on its own motion, the court may in its discretion employ any additional procedures that it concludes will not unduly complicate or prolong the sentencing process."],[0,"(e) Limited Authority To Impose a Sentence Below a Statutory Minimum.—Upon motion of the Government, the court shall have the authority to impose a sentence below a level established by statute as a minimum sentence so as to reflect a defendant's substantial assistance in the investigation or prosecution of another person who has committed an offense. Such sentence shall be imposed in accordance with the guidelines and policy statements issued by the Sentencing Commission pursuant to section 994 of title 28, United States Code."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3553?type=usc&year=mostrecent&link-type=html"},"op":9,"ar":1,"head":"§3553. Imposition of a sentence","tname":"Crimes and Criminal Procedure","by":{"0":"passim, passim, 17, 20, 49, 4, 20, 26, 27, 42, 48, 26, 30, 32, 22, 33, 30, 32, 18, 25, 26, 3, 12, 28, 29, 30, passim, 40, 39"}},{"t":"usc","label":"18 U.S.C. § 3742","url":"https://www.law.cornell.edu/uscode/text/18/3742","subs":["(a)(4)","(b)(4)","(e)","(e)(3)","(e)(4)"],"stext":{"head":"§3742. Review of a sentence","paras":[[0,"(a) Appeal by a Defendant.—A defendant may file a notice of appeal in the district court for review of an otherwise final sentence if the sentence—"],[1,"(1) was imposed in violation of law;"],[1,"(2) was imposed as a result of an incorrect application of the sentencing guidelines; or"],[1,"(3) is greater than the sentence specified in the applicable guideline range to the extent that the sentence includes a greater fine or term of imprisonment, probation, or supervised release than the maximum established in the guideline range, or includes a more limiting condition of probation or supervised release under section 3563(b)(6) or (b)(11) 1 than the maximum established in the guideline range; or"],[1,"(4) was imposed for an offense for which there is no sentencing guideline and is plainly unreasonable."],[0,"(b) Appeal by the Government.—The Government may file a notice of appeal in the district court for review of an otherwise final sentence if the sentence—"],[1,"(1) was imposed in violation of law;"],[1,"(2) was imposed as a result of an incorrect application of the sentencing guidelines;"],[1,"(3) is less than the sentence specified in the applicable guideline range to the extent that the sentence includes a lesser fine or term of imprisonment, probation, or supervised release than the minimum established in the guideline range, or includes a less limiting condition of probation or supervised release under section 3563(b)(6) or (b)(11) 1 than the minimum established in the guideline range; or"],[1,"(4) was imposed for an offense for which there is no sentencing guideline and is plainly unreasonable."],[0,"The Government may not further prosecute such appeal without the personal approval of the Attorney General, the Solicitor General, or a deputy solicitor general designated by the Solicitor General."],[0,"(c) Plea Agreements.—In the case of a plea agreement that includes a specific sentence under rule 11(e)(1)(C) of the Federal Rules of Criminal Procedure—"],[1,"(1) a defendant may not file a notice of appeal under paragraph (3) or (4) of subsection (a) unless the sentence imposed is greater than the sentence set forth in such agreement; and"],[1,"(2) the Government may not file a notice of appeal under paragraph (3) or (4) of subsection (b) unless the sentence imposed is less than the sentence set forth in such agreement."],[0,"(d) Record on Review.—If a notice of appeal is filed in the district court pursuant to subsection (a) or (b), the clerk shall certify to the court of appeals—"],[1,"(1) that portion of the record in the case that is designated as pertinent by either of the parties;"],[1,"(2) the presentence report; and"],[1,"(3) the information submitted during the sentencing proceeding."],[0,"(e) Consideration.—Upon review of the record, the court of appeals shall determine whether the sentence—"],[1,"(1) was imposed in violation of law;"],[1,"(2) was imposed as a result of an incorrect application of the sentencing guidelines;"],[1,"(3) is outside the applicable guideline range, and"],[2,"(A) the district court failed to provide the written statement of reasons required by section 3553(c);"],[2,"(B) the sentence departs from the applicable guideline range based on a factor that—"],[3,"(i) does not advance the objectives set forth in section 3553(a)(2); or"],[3,"(ii) is not authorized under section 3553(b); or"],[3,"(iii) is not justified by the facts of the case; or"],[2,"(C) the sentence departs to an unreasonable degree from the applicable guidelines range, having regard for the factors to be considered in imposing a sentence, as set forth in section 3553(a) of this title and the reasons for the imposition of the particular sentence, as stated by the district court pursuant to the provisions of section 3553(c); or"],[1,"(4) was imposed for an offense for which there is no applicable sentencing guideline and is plainly unreasonable."],[0,"The court of appeals shall give due regard to the opportunity of the district court to judge the credibility of the witnesses, and shall accept the findings of fact of the district court unless they are clearly erroneous and, except with respect to determinations under subsection (3)(A) or (3)(B), shall give due deference to the district court's application of the guidelines to the facts. With respect to determinations under subsection (3)(A) or (3)(B), the court of appeals shall review de novo the district court's application of the guidelines to the facts."],[0,"(f) Decision and Disposition.—If the court of appeals determines that—"],[1,"(1) the sentence was imposed in violation of law or imposed as a result of an incorrect application of the sentencing guidelines, the court shall remand the case for further sentencing proceedings with such instructions as the court considers appropriate;"],[1,"(2) the sentence is outside the applicable guideline range and the district court failed to provide the required statement of reasons in the order of judgment and commitment, or the departure is based on an impermissible factor, or is to an unreasonable degree, or the sentence was imposed for an offense for which there is no applicable sentencing guideline and is plainly unreasonable, it shall state specific reasons for its conclusions and—"],[2,"(A) if it determines that the sentence is too high and the appeal has been filed under subsection (a), it shall set aside the sentence and remand the case for further sentencing proceedings with such instructions as the court considers appropriate, subject to subsection (g);"],[2,"(B) if it determines that the sentence is too low and the appeal has been filed under subsection (b), it shall set aside the sentence and remand the case for further sentencing proceedings with such instructions as the court considers appropriate, subject to subsection (g);"],[1,"(3) the sentence is not described in paragraph (1) or (2), it shall affirm the sentence."],[0,"(g) Sentencing Upon Remand.—A district court to which a case is remanded pursuant to subsection (f)(1) or (f)(2) shall resentence a defendant in accordance with section 3553 and with such instructions as may have been given by the court of appeals, except that—"],[1,"(1) In determining the range referred to in subsection 3553(a)(4), the court shall apply the guidelines issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, and that were in effect on the date of the previous sentencing of the defendant prior to the appeal, together with any amendments thereto by any act of Congress that was in effect on such date; and"],[1,"(2) The court shall not impose a sentence outside the applicable guidelines range except upon a ground that—"],[2,"(A) was specifically and affirmatively included in the written statement of reasons required by section 3553(c) in connection with the previous sentencing of the defendant prior to the appeal; and"],[2,"(B) was held by the court of appeals, in remanding the case, to be a permissible ground of departure."],[0,"(h) Application to a Sentence by a Magistrate Judge.—An appeal of an otherwise final sentence imposed by a United States magistrate judge may be taken to a judge of the district court, and this section shall apply (except for the requirement of approval by the Attorney General or the Solicitor General in the case of a Government appeal) as though the appeal were to a court of appeals from a sentence imposed by a district court."],[0,"(i) Guideline Not Expressed as a Range.—For the purpose of this section, the term \"guideline range\" includes a guideline range having the same upper and lower limits."],[0,"(j) Definitions.—For purposes of this section—"],[1,"(1) a factor is a \"permissible\" ground of departure if it—"],[2,"(A) advances the objectives set forth in section 3553(a)(2); and"],[2,"(B) is authorized under section 3553(b); and"],[2,"(C) is justified by the facts of the case; and"],[1,"(2) a factor is an \"impermissible\" ground of departure if it is not a permissible factor within the meaning of subsection (j)(1)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3742?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§3742. Review of a sentence","tname":"Crimes and Criminal Procedure","by":{"0":"14, 14, 4, 12, 14, 14"}},{"t":"usc","label":"18 U.S.C. § 3162","url":"https://www.law.cornell.edu/uscode/text/18/3162","subs":["(a)(2)"],"by":{"0":"42"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(a)(6)"],"by":{"0":"6"}},{"t":"usc","label":"18 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/18/1001","by":{"0":"2"}},{"t":"usc","label":"18 U.S.C. § 1503","url":"https://www.law.cornell.edu/uscode/text/18/1503","by":{"0":"2"}},{"t":"usc","label":"18 U.S.C. § 1623","url":"https://www.law.cornell.edu/uscode/text/18/1623","by":{"0":"2"}},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(b)"],"by":{"0":"32"}},{"t":"usc","label":"22 U.S.C. § 2778","url":"https://www.law.cornell.edu/uscode/text/22/2778","subs":["(b)(2)"],"stext":{"head":"§2778. Control of arms exports and imports","paras":[[0,"(a) Presidential control of exports and imports of defense articles and services, guidance of policy, etc.; designation of United States Munitions List; issuance of export licenses; negotiations information"],[0,"(1) In furtherance of world peace and the security and foreign policy of the United States, the President is authorized to control the import and the export of defense articles and defense services and to provide foreign policy guidance to persons of the United States involved in the export and import of such articles and services. The President is authorized to designate those items which shall be considered as defense articles and defense services for the purposes of this section and to promulgate regulations for the import and export of such articles and services. The items so designated shall constitute the United States Munitions List."],[0,"(2) Decisions on issuing export licenses under this section shall take into account whether the export of an article would contribute to an arms race, aid in the development of weapons of mass destruction, support international terrorism, increase the possibility of outbreak or escalation of conflict, or prejudice the development of bilateral or multilateral arms control or nonproliferation agreements or other arrangements."],[0,"(3) In exercising the authorities conferred by this section, the President may require that any defense article or defense service be sold under this chapter as a condition of its eligibility for export, and may require that persons engaged in the negotiation for the export of defense articles and services keep the President fully and currently informed of the progress and future prospects of such negotiations."],[0,"(b) Registration and licensing requirements for manufacturers, exporters, or importers of designated defense articles and defense services"],[0,"(1)(A)(i) As prescribed in regulations issued under this section, every person (other than an officer or employee of the United States Government acting in an official capacity) who engages in the business of manufacturing, exporting, or importing any defense articles or defense services designated by the President under subsection (a)(1) shall register with the United States Government agency charged with the administration of this section, and shall pay a registration fee which shall be prescribed by such regulations. Such regulations shall prohibit the return to the United States for sale in the United States (other than for the Armed Forces of the United States and its allies or for any State or local law enforcement agency) of any military firearms or ammunition of United States manufacture furnished to foreign governments by the United States under this chapter or any other foreign assistance or sales program of the United States, whether or not enhanced in value or improved in condition in a foreign country. This prohibition shall not extend to similar firearms that have been so substantially transformed as to become, in effect, articles of foreign manufacture."],[0,"(ii)(I) As prescribed in regulations issued under this section, every person (other than an officer or employee of the United States Government acting in official capacity) who engages in the business of brokering activities with respect to the manufacture, export, import, or transfer of any defense article or defense service designated by the President under subsection (a)(1), or in the business of brokering activities with respect to the manufacture, export, import, or transfer of any foreign defense article or defense service (as defined in subclause (IV)), shall register with the United States Government agency charged with the administration of this section, and shall pay a registration fee which shall be prescribed by such regulations."],[0,"(II) Such brokering activities shall include the financing, transportation, freight forwarding, or taking of any other action that facilitates the manufacture, export, or import of a defense article or defense service."],[0,"(III) No person may engage in the business of brokering activities described in subclause (I) without a license, issued in accordance with this chapter, except that no license shall be required for such activities undertaken by or for an agency of the United States Government—"],[1,"(aa) for use by an agency of the United States Government; or"],[1,"(bb) for carrying out any foreign assistance or sales program authorized by law and subject to the control of the President by other means."],[0,"(IV) For purposes of this clause, the term \"foreign defense article or defense service\" includes any non-United States defense article or defense service of a nature described on the United States Munitions List regardless of whether such article or service is of United States origin or whether such article or service contains United States origin components."],[0,"(B) The prohibition under such regulations required by the second sentence of subparagraph (A) shall not extend to any military firearms (or ammunition, components, parts, accessories, and attachments for such firearms) of United States manufacture furnished to any foreign government by the United States under this chapter or any other foreign assistance or sales program of the United States if—"],[1,"(i) such firearms are among those firearms that the Secretary of the Treasury is, or was at any time, required to authorize the importation of by reason of the provisions of section 925(e) of title 18 (including the requirement for the listing of such firearms as curios or relics under section 921(a)(13) of that title); and"],[1,"(ii) such foreign government certifies to the United States Government that such firearms are owned by such foreign government."],[0,"(C) A copy of each registration made under this paragraph shall be transmitted to the Secretary of the Treasury for review regarding law enforcement concerns. The Secretary shall report to the President regarding such concerns as necessary."],[0,"(2) Except as otherwise specifically provided in regulations issued under subsection (a)(1), no defense articles or defense services designated by the President under subsection (a)(1) may be exported or imported without a license for such export or import, issued in accordance with this chapter and regulations issued under this chapter, except that no license shall be required for exports or imports made by or for an agency of the United States Government (A) for official use by a department or agency of the United States Government, or (B) for carrying out any foreign assistance or sales program authorized by law and subject to the control of the President by other means."],[0,"(3)(A) For each of the fiscal years 1988 and 1989, $250,000 of registration fees collected pursuant to paragraph (1) shall be credited to a Department of State account, to be available without fiscal year limitation. Fees credited to that account shall be available only for the payment of expenses incurred for—"],[1,"(i) contract personnel to assist in the evaluation of munitions control license applications, reduce processing time for license applications, and improve monitoring of compliance with the terms of licenses; and"],[1,"(ii) the automation of munitions control functions and the processing of munitions control license applications, including the development, procurement, and utilization of computer equipment and related software."],[0,"(B) The authority of this paragraph may be exercised only to such extent or in such amounts as are provided in advance in appropriation Acts."],[0,"(c) Criminal violations; punishment"],[0,"Any person who willfully violates any provision of this section, section 2779 of this title, a treaty referred to in subsection (j)(1)(C)(i), or any rule or regulation issued under this section or section 2779 of this title, including any rule or regulation issued to implement or enforce a treaty referred to in subsection (j)(1)(C)(i) or an implementing arrangement pursuant to such treaty, or who willfully, in a registration or license application or required report, makes any untrue statement of a material fact or omits to state a material fact required to be stated therein or necessary to make the statements therein not misleading, shall upon conviction be fined for each violation not more than $1,000,000 or imprisoned not more than 20 years, or both."],[0,"(d) Repealed. Pub. L. 96–70, title III, §3303(a)(4), Sept. 27, 1979, 93 Stat. 499"],[0,"(e) Enforcement powers of President"],[0,"In carrying out functions under this section with respect to the export of defense articles and defense services, including defense articles and defense services exported or imported pursuant to a treaty referred to in subsection (j)(1)(C)(i), the President is authorized to exercise the same powers concerning violations and enforcement which are conferred upon departments, agencies and officials by subsections (c) and (d) of section 1760 of the Export Control Reform Act of 2018 (50 U.S.C. 4819), and by subsections (a)(1), (a)(2), (a)(3), (a)(4), (a)(7), (c), and (h) of section 1761 of such Act (50 U.S.C. 4820), subject to the same terms and conditions as are applicable to such powers under such Act, except that section 1760(c)(2) of such Act (50 U.S.C. 4819(c)(2)) shall not apply, and instead, as prescribed in regulations issued under this section, the Secretary of State may assess civil penalties for violations of this chapter and regulations prescribed thereunder and further may commence a civil action to recover such civil penalties, and except further that the names of the countries and the types and quantities of defense articles for which licenses are issued under this section shall not be withheld from public disclosure unless the President determines that the release of such information would be contrary to the national interest. Nothing in this subsection shall be construed as authorizing the withholding of information from the Congress. Notwithstanding section section 1 1760(c) of the Export Control Reform Act of 2018 (50 U.S.C. 4819(c)), the civil penalty for each violation involving controls imposed on the export of defense articles and defense services under this section may not exceed the greater of $1,200,000 or the amount that is twice the value of the transaction that is the basis of the violation with respect to which the penalty is imposed..1"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/2778?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2778. Control of arms exports and imports","tname":"Foreign Relations and Intercourse","by":{"0":"5"}},{"t":"usc","label":"26 U.S.C. § 5841","url":"https://www.law.cornell.edu/uscode/text/26/5841","by":{"0":"2"}},{"t":"usc","label":"26 U.S.C. § 5845","url":"https://www.law.cornell.edu/uscode/text/26/5845","subs":["(a)(6)","(b)"],"by":{"0":"2, 2"}},{"t":"usc","label":"26 U.S.C. § 5861","url":"https://www.law.cornell.edu/uscode/text/26/5861","by":{"0":"2"}},{"t":"usc","label":"28 U.S.C. § 991","url":"https://www.law.cornell.edu/uscode/text/28/991","subs":["(b)(1)(A)","(b)(1)(B)"],"stext":{"head":"§991. United States Sentencing Commission; establishment and purposes","paras":[[0,"(a) There is established as an independent commission in the judicial branch of the United States a United States Sentencing Commission which shall consist of seven voting members and one nonvoting member. The President, after consultation with representatives of judges, prosecuting attorneys, defense attorneys, law enforcement officials, senior citizens, victims of crime, and others interested in the criminal justice process, shall appoint the voting members of the Commission, by and with the advice and consent of the Senate, one of whom shall be appointed, by and with the advice and consent of the Senate, as the Chair and three of whom shall be designated by the President as Vice Chairs. At least 3 of the members shall be Federal judges selected after considering a list of six judges recommended to the President by the Judicial Conference of the United States. Not more than four of the members of the Commission shall be members of the same political party, and of the three Vice Chairs, no more than two shall be members of the same political party. The Attorney General, or the Attorney General's designee, shall be an ex officio, nonvoting member of the Commission. The Chair, Vice Chairs, and members of the Commission shall be subject to removal from the Commission by the President only for neglect of duty or malfeasance in office or for other good cause shown."],[0,"(b) The purposes of the United States Sentencing Commission are to—"],[1,"(1) establish sentencing policies and practices for the Federal criminal justice system that—"],[2,"(A) assure the meeting of the purposes of sentencing as set forth in section 3553(a)(2) of title 18, United States Code;"],[2,"(B) provide certainty and fairness in meeting the purposes of sentencing, avoiding unwarranted sentencing disparities among defendants with similar records who have been found guilty of similar criminal conduct while maintaining sufficient flexibility to permit individualized sentences when warranted by mitigating or aggravating factors not taken into account in the establishment of general sentencing practices; and"],[2,"(C) reflect, to the extent practicable, advancement in knowledge of human behavior as it relates to the criminal justice process; and"],[1,"(2) develop means of measuring the degree to which the sentencing, penal, and correctional practices are effective in meeting the purposes of sentencing as set forth in section 3553(a)(2) of title 18, United States Code."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/991?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§991. United States Sentencing Commission; establishment and purposes","tname":"Judiciary and Judicial Procedure","by":{"0":"17, 42, 17"}},{"t":"usc","label":"28 U.S.C. § 994","url":"https://www.law.cornell.edu/uscode/text/28/994","subs":["(c)","(e)","(f)","(m)","(p)"],"stext":{"head":"§994. Duties of the Commission","paras":[[0,"(a) The Commission, by affirmative vote of at least four members of the Commission, and pursuant to its rules and regulations and consistent with all pertinent provisions of any Federal statute shall promulgate and distribute to all courts of the United States and to the United States Probation System—"],[1,"(1) guidelines, as described in this section, for use of a sentencing court in determining the sentence to be imposed in a criminal case, including—"],[2,"(A) a determination whether to impose a sentence to probation, a fine, or a term of imprisonment;"],[2,"(B) a determination as to the appropriate amount of a fine or the appropriate length of a term of probation or a term of imprisonment;"],[2,"(C) a determination whether a sentence to a term of imprisonment should include a requirement that the defendant be placed on a term of supervised release after imprisonment, and, if so, the appropriate length of such a term;"],[2,"(D) a determination whether multiple sentences to terms of imprisonment should be ordered to run concurrently or consecutively; and"],[2,"(E) a determination under paragraphs (6) and (11) 1 of section 3563(b) of title 18;"],[1,"(2) general policy statements regarding application of the guidelines or any other aspect of sentencing or sentence implementation that in the view of the Commission would further the purposes set forth in section 3553(a)(2) of title 18, United States Code, including the appropriate use of—"],[2,"(A) the sanctions set forth in sections 3554, 3555, and 3556 of title 18;"],[2,"(B) the conditions of probation and supervised release set forth in sections 3563(b) and 3583(d) of title 18;"],[2,"(C) the sentence modification provisions set forth in sections 3563(c), 3564, 3573, and 3582(c) of title 18;"],[2,"(D) the fine imposition provisions set forth in section 3572 of title 18;"],[2,"(E) the authority granted under rule 11(e)(2) of the Federal Rules of Criminal Procedure to accept or reject a plea agreement entered into pursuant to rule 11(e)(1); and"],[2,"(F) the temporary release provisions set forth in section 3622 of title 18, and the prerelease custody provisions set forth in section 3624(c) of title 18; and"],[1,"(3) guidelines or general policy statements regarding the appropriate use of the provisions for revocation of probation set forth in section 3565 of title 18, and the provisions for modification of the term or conditions of supervised release and revocation of supervised release set forth in section 3583(e) of title 18."],[0,"(b)(1) The Commission, in the guidelines promulgated pursuant to subsection (a)(1), shall, for each category of offense involving each category of defendant, establish a sentencing range that is consistent with all pertinent provisions of title 18, United States Code."],[0,"(2) If a sentence specified by the guidelines includes a term of imprisonment, the maximum of the range established for such a term shall not exceed the minimum of that range by more than the greater of 25 percent or 6 months, except that, if the minimum term of the range is 30 years or more, the maximum may be life imprisonment."],[0,"(c) The Commission, in establishing categories of offenses for use in the guidelines and policy statements governing the imposition of sentences of probation, a fine, or imprisonment, governing the imposition of other authorized sanctions, governing the size of a fine or the length of a term of probation, imprisonment, or supervised release, and governing the conditions of probation, supervised release, or imprisonment, shall consider whether the following matters, among others, have any relevance to the nature, extent, place of service, or other incidents 2 of an appropriate sentence, and shall take them into account only to the extent that they do have relevance—"],[1,"(1) the grade of the offense;"],[1,"(2) the circumstances under which the offense was committed which mitigate or aggravate the seriousness of the offense;"],[1,"(3) the nature and degree of the harm caused by the offense, including whether it involved property, irreplaceable property, a person, a number of persons, or a breach of public trust;"],[1,"(4) the community view of the gravity of the offense;"],[1,"(5) the public concern generated by the offense;"],[1,"(6) the deterrent effect a particular sentence may have on the commission of the offense by others; and"],[1,"(7) the current incidence of the offense in the community and in the Nation as a whole."],[0,"(d) The Commission in establishing categories of defendants for use in the guidelines and policy statements governing the imposition of sentences of probation, a fine, or imprisonment, governing the imposition of other authorized sanctions, governing the size of a fine or the length of a term of probation, imprisonment, or supervised release, and governing the conditions of probation, supervised release, or imprisonment, shall consider whether the following matters, among others, with respect to a defendant, have any relevance to the nature, extent, place of service, or other incidents 2 of an appropriate sentence, and shall take them into account only to the extent that they do have relevance—"],[1,"(1) age;"],[1,"(2) education;"],[1,"(3) vocational skills;"],[1,"(4) mental and emotional condition to the extent that such condition mitigates the defendant's culpability or to the extent that such condition is otherwise plainly relevant;"],[1,"(5) physical condition, including drug dependence;"],[1,"(6) previous employment record;"],[1,"(7) family ties and responsibilities;"],[1,"(8) community ties;"],[1,"(9) role in the offense;"],[1,"(10) criminal history; and"],[1,"(11) degree of dependence upon criminal activity for a livelihood."],[0,"The Commission shall assure that the guidelines and policy statements are entirely neutral as to the race, sex, national origin, creed, and socioeconomic status of offenders."],[0,"(e) The Commission shall assure that the guidelines and policy statements, in recommending a term of imprisonment or length of a term of imprisonment, reflect the general inappropriateness of considering the education, vocational skills, employment record, family ties and responsibilities, and community ties of the defendant."],[0,"(f) The Commission, in promulgating guidelines pursuant to subsection (a)(1), shall promote the purposes set forth in section 991(b)(1), with particular attention to the requirements of subsection 991(b)(1)(B) for providing certainty and fairness in sentencing and reducing unwarranted sentence disparities."],[0,"(g) The Commission, in promulgating guidelines pursuant to subsection (a)(1) to meet the purposes of sentencing as set forth in section 3553(a)(2) of title 18, United States Code, shall take into account the nature and capacity of the penal, correctional, and other facilities and services available, and shall make recommendations concerning any change or expansion in the nature or capacity of such facilities and services that might become necessary as a result of the guidelines promulgated pursuant to the provisions of this chapter. The sentencing guidelines prescribed under this chapter shall be formulated to minimize the likelihood that the Federal prison population will exceed the capacity of the Federal prisons, as determined by the Commission."],[0,"(h) The Commission shall assure that the guidelines specify a sentence to a term of imprisonment at or near the maximum term authorized for categories of defendants in which the defendant is eighteen years old or older and—"],[1,"(1) has been convicted of a felony that is—"],[2,"(A) a crime of violence; or"],[2,"(B) an offense described in section 401 of the Controlled Substances Act (21 U.S.C. 841), sections 1002(a), 1005, and 1009 of the Controlled Substances Import and Export Act (21 U.S.C. 952(a), 955, and 959), and chapter 705 of title 46; and"],[1,"(2) has previously been convicted of two or more prior felonies, each of which is—"],[2,"(A) a crime of violence; or"],[2,"(B) an offense described in section 401 of the Controlled Substances Act (21 U.S.C. 841), sections 1002(a), 1005, and 1009 of the Controlled Substances Import and Export Act (21 U.S.C. 952(a), 955, and 959), and chapter 705 of title 46."],[0,"(i) The Commission shall assure that the guidelines specify a sentence to a substantial term of imprisonment for categories of defendants in which the defendant—"],[1,"(1) has a history of two or more prior Federal, State, or local felony convictions for offenses committed on different occasions;"],[1,"(2) committed the offense as part of a pattern of criminal conduct from which the defendant derived a substantial portion of the defendant's income;"],[1,"(3) committed the offense in furtherance of a conspiracy with three or more persons engaging in a pattern of racketeering activity in which the defendant participated in a managerial or supervisory capacity;"],[1,"(4) committed a crime of violence that constitutes a felony while on release pending trial, sentence, or appeal from a Federal, State, or local felony for which he was ultimately convicted; or"],[1,"(5) committed a felony that is set forth in section 401 or 1010 of the Comprehensive Drug Abuse Prevention and Control Act of 1970 (21 U.S.C. 841 and 960), and that involved trafficking in a substantial quantity of a controlled substance."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/994?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§994. Duties of the Commission","tname":"Judiciary and Judicial Procedure","by":{"0":"17, 17, 20, 21, 17, 17, 18, 18"}}]};